# Just like in interviews, please do not use python libraries to take shortcuts.
# They aren't usually allowed in real interviews.
# Add comments to each step of your logic

def validIPAddress(queryIP):
    def is_valid_ipv4(ip):
        parts = ip.split('.')

        # Must have exactly 4 parts
        if len(parts) != 4:
            return False

        for part in parts:
            # Each part must be non-empty
            if not part:
                return False

            # Check for leading zeros (except "0" itself)
            if len(part) > 1 and part[0] == '0':
                return False

            # Must contain only digits
            if not part.isdigit():
                return False

            # Must be in range [0, 255]
            num = int(part)
            if num > 255:
                return False

        return True

    def is_valid_ipv6(ip):
        parts = ip.split(':')

        # Must have exactly 8 parts
        if len(parts) != 8:
            return False

        for part in parts:
            # Each part must be non-empty and 1-4 characters
            if not part or len(part) > 4:
                return False

            # Must contain only valid hexadecimal characters
            for char in part:
                if not ((char >= '0' and char <= '9') or 
                       (char >= 'a' and char <= 'f') or 
                       (char >= 'A' and char <= 'F')):
                    return False

        return True

    # Determine IP type by looking for delimiters
    if '.' in queryIP and ':' not in queryIP:
        # Potential IPv4
        if is_valid_ipv4(queryIP):
            return "IPv4"
    elif ':' in queryIP and '.' not in queryIP:
        # Potential IPv6
        if is_valid_ipv6(queryIP):
            return "IPv6"

    return "Neither"

